#include <vector>
#include <complex>
#include <algorithm>
#include <cmath>
#include <omp.h>

void sortComplexByMagnitude(std::vector<std::complex<double>> &x) {
    const std::size_t n = x.size();
    if (n < 2) return;

    // Parallel stable merge sort using OpenMP tasks.
    // We compare by squared magnitude to avoid unnecessary square roots.
    std::vector<std::complex<double>> buffer(n);

    auto mag2 = [](const std::complex<double>& z) -> double {
        return z.real() * z.real() + z.imag() * z.imag();
    };

    auto lessByMagnitude = [&](const std::complex<double>& a,
                               const std::complex<double>& b) -> bool {
        const double ma = mag2(a);
        const double mb = mag2(b);
        if (ma < mb) return true;
        if (ma > mb) return false;
        // Deterministic tie-breakers for equal magnitudes.
        if (a.real() < b.real()) return true;
        if (a.real() > b.real()) return false;
        return a.imag() < b.imag();
    };

    const std::size_t serial_threshold = 2048;

    struct Sorter {
        static void sortRange(std::vector<std::complex<double>>& data,
                              std::vector<std::complex<double>>& temp,
                              std::size_t left,
                              std::size_t right,
                              std::size_t threshold,
                              const decltype(lessByMagnitude)& comp) {
            const std::size_t len = right - left;
            if (len <= 1) return;

            if (len <= threshold) {
                std::stable_sort(data.begin() + static_cast<std::ptrdiff_t>(left),
                                 data.begin() + static_cast<std::ptrdiff_t>(right),
                                 comp);
                return;
            }

            const std::size_t mid = left + len / 2;

            #pragma omp task default(none) firstprivate(left, mid, threshold) shared(data, temp, comp)
            {
                sortRange(data, temp, left, mid, threshold, comp);
            }

            #pragma omp task default(none) firstprivate(mid, right, threshold) shared(data, temp, comp)
            {
                sortRange(data, temp, mid, right, threshold, comp);
            }

            #pragma omp taskwait

            std::size_t i = left;
            std::size_t j = mid;
            std::size_t k = left;

            while (i < mid && j < right) {
                if (comp(data[j], data[i])) {
                    temp[k++] = data[j++];
                } else {
                    temp[k++] = data[i++];
                }
            }
            while (i < mid) temp[k++] = data[i++];
            while (j < right) temp[k++] = data[j++];

            std::copy(temp.begin() + static_cast<std::ptrdiff_t>(left),
                      temp.begin() + static_cast<std::ptrdiff_t>(right),
                      data.begin() + static_cast<std::ptrdiff_t>(left));
        }
    };

    #pragma omp parallel
    {
        #pragma omp single
        {
            Sorter::sortRange(x, buffer, 0, n, serial_threshold, lessByMagnitude);
        }
    }
}
